async function api(route,data={},retry=true){mutationVersion++;let r=await fetch('/api/'+route,{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify(data)});if(r.status===403&&retry){try{const s=await(await fetch('/api/session')).json();if(s.csrf&&s.csrf!==csrf){csrf=s.csrf;return api(route,data,false);}}catch{}}const d=await r.json();if(r.status===401)showLogin();if(!r.ok)throw Object.assign(Error(d.error||'No se pudo completar la acción.'),{status:r.status,code:d.code,retryAfterSeconds:d.retryAfterSeconds});if(d.state){state=d.state;render();}return d;}
