async function startWorkspace(){await refresh();if(!state)return;countries=[...state.settings.countries];$('#loginScreen').hidden=true;$('#workspace').hidden=false;$('#seed').value=state.settings.lastSeed?(/^https?:/.test(state.settings.lastSeed)?state.settings.lastSeed:'https://www.instagram.com/'+state.settings.lastSeed+'/'):'';$('#cities').value=state.settings.cities||'';$('#offer').value=state.settings.offer||'';segments=String(state.settings.segment||'Hoteles').split(/\s*,\s*/).filter(Boolean);segmentSummary();$('#businessTier').value=state.settings.businessTier||'premium';$('#searchTarget').value=String(state.settings.maxResults||20);$('#searchDepth').value=state.settings.searchDepth||'quick';$('#verifyActivity').checked=!!state.settings.verifyActivity;$('#clearOnSearch').checked=state.settings.clearOnSearch!==false;countrySummary();if(state.search?.ids?.length)view='new';$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',String(b.dataset.view===view));});render();}
