function status(l){if(isActive(l)&&!contacted(l)&&!l.dnc)return ['Cuenta activa','muted'];if(available(l)&&!qualified(l))return ['Por verificar','review'];if(l.dnc)return ['No contactar','muted'];if(l.eventStatus==='uncertain'||l.eventStatus==='pending')return ['Revisar envío','warning'];if(l.eventStatus==='contacted')return ['Conversación previa','sent'];if(contacted(l))return ['Enviado','sent'];if(l.block.includes('Cupo'))return ['Cupo alcanzado','warning'];return [qualified(l)?'Listo para contactar':'Por revisar',qualified(l)?'ready':'review'];}
const audit=l=>{try{return JSON.parse(l.qualification||'null');}catch{return null;}};
const activityOf=l=>{try{return JSON.parse(l.activity||'{}');}catch{return {};}},isActive=l=>activityOf(l).verdict==='active';
function activityLine(l){const a=activityOf(l),ago=a.days!=null?` · última publicación hace ${a.days} ${a.days===1?'día':'días'}`:'',w=a.weeks!=null&&a.posts?` · publicó en ${a.weeks} de ${a.span||12} semanas`:'',how=a.source==='index'?' (estimado con el buscador)':a.source==='user'?' (marcado por vos)':' (revisado en el perfil)';return a.verdict==='active'?`Publica seguido${w}${ago}${how}. No se le escribe.`:a.verdict==='irregular'?`Publica de forma irregular${w}${ago}${how}.`:a.verdict==='inactive'?`Casi inactiva${w}${ago}${how}.`:'Actividad sin verificar: abrí el perfil y fijate cada cuánto publica.';}
const available=l=>!l.dnc&&!contacted(l)&&!isActive(l);
const qualified=l=>!!l.demo||audit(l)?.status==='ready';
const isSelectable=l=>!l.dnc&&!l.archived&&!l.eventStatus&&!isActive(l);
const contacted=l=>['sent','contacted'].includes(l.eventStatus)||/^(Espera|Ya contactado)/.test(l.block||'');
const isPending=l=>isSelectable(l)&&qualified(l);
const activitySummary=l=>{const a=activityOf(l);return a.lastPost?'Última publicación: '+date(a.lastPost+'T12:00:00-03:00'):a.source==='profile'?'Sin publicaciones en el perfil':'Actividad pendiente de revisar';};
const displayName=l=>String(String(l.name||'').replace('DEMO · ','')||'').replace(/\s*[•·]\s*Instagram( photos and videos| fotos y videos)?.*$/i,'').replace(/\s*\(@[^)]*\)?.*$/,'').replace(/\s+\|\s+.*$/,'').trim()||'@'+l.handle;
