function reportImport(r){toast(`${r.added} nuevos · ${r.duplicates} ya existentes · ${r.history} envíos recuperados${r.rejected?' · '+r.rejected+' filas rechazadas':''}${r.errors?.length?'. '+r.errors.join(' / '):''}`,r.rejected>0);}
$('#importOpen').onclick=()=>$('#importDialog').showModal();$('#importFile').onchange=()=>run(async()=>{const file=$('#importFile').files[0];if(!file)return;if(file.size>8e6)throw Error('El archivo supera 8 MB.');const format=file.name.toLowerCase().endsWith('.xlsx')?'xlsx':file.name.toLowerCase().endsWith('.csv')?'csv':'json';let content;if(format==='xlsx'){const b=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<b.length;i+=32768)binary+=String.fromCharCode(...b.subarray(i,i+32768));content=btoa(binary);}else content=await file.text();const r=await api('import',{format,content});$('#importDialog').close();$('#importFile').value='';reportImport(r);});
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;tablePage=0;$$('[data-view]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-selected',String(n===b));});renderRows();});$('#listSearch').oninput=()=>{tablePage=0;renderRows();};$('#listCountry').onchange=()=>{tablePage=0;renderRows();};$('#selectAll').onchange=e=>{for(const l of filtered().slice(tablePage*PAGE_SIZE,(tablePage+1)*PAGE_SIZE).filter(isSelectable)){if(e.target.checked&&selected.size<100)selected.add(l.id);else if(!e.target.checked)selected.delete(l.id);}renderRows();};$('#leadRows').onchange=e=>{const id=Number(e.target.dataset.select);if(!id)return;if(e.target.checked){if(selected.size>=100){e.target.checked=false;toast('La cola admite hasta 100 clientes por vez.',true);return;}selected.add(id);}else selected.delete(id);renderRows();};$('#leadRows').onclick=e=>{const b=e.target.closest('[data-review]');if(b)openLead(Number(b.dataset.review));};
function renderAudit(l){const a=audit(l);$('#hotelAudit').innerHTML=a?`<strong>${esc(a.manual?'Revisado por vos':a.label)}</strong><p>${esc(a.businessDetail||'Actividad comercial pendiente de confirmar.')}</p><p>${esc(a.feedDetail||'Feed pendiente de verificar.')}</p><small>${esc(activityLine(l))}</small><div>${[[a.businessSource,'Actividad comercial'],[a.feedSource,'Evidencia del feed']].filter(x=>/^https?:\/\//.test(x[0]||'')).map(([url,label])=>`<a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)} ↗</a>`).join(' · ')}</div>`:`<p>Este contacto todavía no tiene un análisis de actividad comercial y contenido. Revisá el perfil antes de contactar.</p><small>${esc(activityLine(l))}</small>`;$('#manualReviewLabel').hidden=qualified(l);}
function openLead(id){activeLead=id;const l=state.leads.find(l=>l.id===id);$('#proposalName').textContent=displayName(l);$('#proposalLocation').textContent=[l.city,l.country].filter(Boolean).join(' · ');$('#manualReview').checked=false;$('#manualReviewLabel').hidden=qualified(l);$('#proposalText').value=l.message;$('#proposalEmail').value=l.email||'';renderAudit(l);$('#proposalReason').textContent=l.score_reason+' '+l.reason;$('#proposalScore').textContent=`Afinidad ${l.score}/100`;$('#proposalSource').href=l.source;$('#proposalProfile').href=`https://www.instagram.com/${l.handle}/`;$('#doNotContact').checked=!!l.dnc;updateProposalStatus();$('#leadDialog').showModal();}
function updateProposalStatus(){const l=state.leads.find(l=>l.id===activeLead);if(!l)return;const unverified=!qualified(l)&&!$('#manualReview').checked;const blocked=unverified||l.block&&!l.block.startsWith('Revisar hotel')&&!l.block.startsWith('Verificá el hotel');$('#proposalStatus').textContent=l.demo?'Ejemplo ficticio. No se enviarán mensajes reales.':unverified?'Revisá el hotel y su contenido; después marcá la confirmación.':blocked?l.block:'Revisá el perfil y el texto antes de contactar.';$('#copyOpen').disabled=!!blocked;$('#markSent').disabled=!!blocked;$('#copyOpen').textContent=l.demo?'Copiar ejemplo':'Copiar y abrir Instagram ↗';$('#markSent').textContent=l.demo?'Simular envío ✓':'Ya envié por Instagram ✓';const eb=l.emailBlock||'';$('#sendEmailOne').disabled=l.demo||unverified||!state.email.configured||!$('#proposalEmail').value.trim()||!!eb&&!/^(Revisar hotel|Verificá el hotel|Falta el email)/.test(eb);$('#sendEmailOne').textContent=!state.email.configured?'✉ Configurá tu email en Ajustes':'✉ Enviar por email';}
async function saveLead(approve=false){await api('update',{id:activeLead,message:$('#proposalText').value,email:$('#proposalEmail').value,dnc:$('#doNotContact').checked,...($('#manualReview').checked?{qualificationReviewed:true}:{}),...(approve?{approved:true}:{})});}
$('#manualReview').onchange=updateProposalStatus;$('#proposalEmail').oninput=updateProposalStatus;$('#sendEmailOne').onclick=()=>run(async()=>{const to=$('#proposalEmail').value.trim();if(!confirm(`¿Enviar esta propuesta por email a ${to}${state.email.attachment?' con '+state.email.attachment:''}?`))return;await saveLead(true);const r=await api('email/send',{ids:[activeLead],confirm:true});$('#leadDialog').close();toast('Email en proceso. Podés seguir trabajando y ver el resultado arriba.');},$('#sendEmailOne'));$('#saveProposal').onclick=()=>run(async()=>{await saveLead();toast('Propuesta guardada.');});$('#doNotContact').onchange=()=>run(()=>saveLead());$('#copyOpen').onclick=()=>{const l=state.leads.find(l=>l.id===activeLead);const copied=copyText($('#proposalText').value);if(!l.demo)openChat(l.handle);run(async()=>{await copied.catch(()=>{throw Error('No se pudo copiar. Seleccioná el texto de la propuesta y copialo con Ctrl+C.');});await saveLead(true);toast('Mensaje copiado. En el chat pegalo con Ctrl+V, tocá Enviar y volvé para tocar «Ya lo envié».');});};let manualIds=[];
$('#markSent').onclick=()=>run(async()=>{const l=state.leads.find(l=>l.id===activeLead);if(!confirm(l.demo?'¿Simular este envío ficticio?':`¿Ya enviaste esta propuesta a @${l.handle}?`))return;await saveLead(true);await api('manual',{id:activeLead,confirm:true});$('#leadDialog').close();if(manualIds.length)nextManual();toast('Registrado. El cliente queda tachado y no se le vuelve a escribir.');});
