$('#startQueue').onclick=()=>run(async()=>{if(!state.instagram){settings();$('#instagramSettings').open=true;toast('Conectá Instagram para iniciar una tanda automática oficial.',true);return;}const batch=await api('instagram/batch/preview',{ids:[...selected]});$('#queuePreviewSummary').textContent=batch.selected+' seleccionados · '+batch.items.length+' habilitados ahora por Meta y cupo · remitente @'+batch.account.username;$('#queuePreview').innerHTML=batch.items.map(l=>'<article><strong>'+esc(l.name)+' · @'+esc(l.handle)+'</strong><p>'+esc(l.message)+'</p></article>').join('')+batch.skipped.map(l=>'<small>'+esc(state.leads.find(v=>v.id===l.id)?.name||'Cliente')+': '+esc(l.reason)+'</small><br>').join('');$('#queueConsent').checked=false;$('#confirmQueue').disabled=true;$('#confirmQueue').dataset.ids=JSON.stringify(batch.items.map(l=>l.id));$('#confirmQueue').dataset.token=batch.token;$('#confirmQueue').dataset.eligible=String(batch.items.length);$('#queueDialog').showModal();});
