$('#emailSelection').onclick=()=>run(async()=>{if(!state.email.configured){settings();$('#emailSettings').open=true;toast('Configurá tu casilla para enviar emails.',true);return;}const batch=await api('batch/preview',{ids:[...selected],channel:'email'});$('#emailPreviewSummary').textContent=batch.selected+' seleccionados · '+batch.items.length+' en esta tanda por prioridad · '+batch.skipped.length+' omitidos o para después. Adjunto: '+(state.email.attachment||'ninguno');$('#emailPreview').innerHTML=batch.items.map(l=>'<article><strong>'+esc(l.name)+' · '+esc(l.email)+'</strong><p>'+esc(l.message)+'</p></article>').join('');$('#emailConsent').checked=false;$('#confirmEmail').disabled=true;$('#confirmEmail').dataset.token=batch.token;$('#confirmEmail').dataset.ids=JSON.stringify(batch.items.map(l=>l.id));$('#emailDialog').showModal();});$('#emailConsent').onchange=()=>$('#confirmEmail').disabled=!$('#emailConsent').checked||JSON.parse($('#confirmEmail').dataset.ids||'[]').length===0;$('#confirmEmail').onclick=()=>run(async()=>{const ids=JSON.parse($('#confirmEmail').dataset.ids);$('#confirmEmail').textContent='Enviando…';try{const r=await api('email/send',{ids,confirm:true,reviewed:true,token:$('#confirmEmail').dataset.token});selected.clear();$('#emailDialog').close();toast(`${r.started} emails en proceso. Podés seguir trabajando; el progreso aparece arriba.`);}finally{$('#confirmEmail').textContent='Enviar emails';}},$('#confirmEmail'));
