$('#historyOpen').onclick=()=>{const labels={sent:'Enviado',contacted:'Conversación previa · sin nuevo envío',failed:'No enviado',pending:'Pendiente',uncertain:'Revisar resultado'};$('#historyList').innerHTML=state.history.length?state.history.map(e=>`<article class="history-item"><strong>${esc(e.name)} <small>${esc(date(e.at))} · ${esc(labels[e.status])}</small></strong>${e.status==='contacted'?`<p class="small-note">${esc(e.receipt)}. Fecha de detección; no se conoce la fecha del mensaje anterior.</p>`:`<details><summary>Ver propuesta</summary><p>${esc(e.message)}</p></details>`}${e.status==='uncertain'?`<div class="two"><button data-reconcile="${e.id}" data-result="sent" class="subtle-button">Verifiqué: se envió</button><button data-reconcile="${e.id}" data-result="failed" class="subtle-button">Verifiqué: no se envió</button></div>`:''}</article>`).join(''):'<p>Todavía no registraste propuestas.</p>';$('#historyDialog').showModal();};$('#historyList').onclick=e=>{const b=e.target.closest('[data-reconcile]');if(b&&confirm('¿Revisaste el resultado real en Instagram?'))run(async()=>{await api('reconcile',{event:Number(b.dataset.reconcile),status:b.dataset.result});$('#historyDialog').close();toast('Historial actualizado.');});};$('#demoButton').onclick=()=>run(async()=>{await api('demo');toast('Tres ejemplos ficticios cargados para probar la planilla.');});$('#clearDemo').onclick=()=>run(()=>api('clear-demo'));$('#downloadExcel').onclick=()=>toast('Descargando tu planilla actualizada.');$('#quitApp').onclick=()=>run(async()=>{if(!confirm('¿Cerrar Nexo? Tus datos quedan guardados.'))return;await api('quit');document.body.innerHTML='<section class="closed"><h1>Nexo está cerrado.</h1><p>Tu planilla quedó guardada. Para volver, abrí Nexo.</p></section>';window.close();});

const SCHEDULE_LABELS={pending:'Programado',due:'Toca enviar',sent:'Enviado',failed:'No enviado',cancelled:'Cancelado'};
function when(v){return new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v));}
function renderSchedules(){const list=state.schedules,open=list.filter(x=>['pending','due'].includes(x.status)),due=list.filter(x=>x.status==='due');$('#updateNotice').hidden=state.build===PAGE_BUILD;$('#scheduledCount').textContent=open.length?String(open.length):'';$('#dueNotice').hidden=!due.length;$('#dueTitle').textContent=`Hoy toca enviar por Instagram a ${due.length} ${due.length===1?'hotel':'hoteles'}`;$('#schedulesList').innerHTML=list.length?list.map(x=>`<article class="history-item"><strong>${esc(x.name)} <small>${esc(when(x.at))} · ${x.channel==='email'?'✉ '+esc(x.email||''):'Instagram @'+esc(x.handle)} · ${esc(SCHEDULE_LABELS[x.status]||x.status)}</small></strong>${x.note&&x.status!=='sent'?`<p class="small-note">${esc(x.note)}</p>`:''}<div class="two">${x.status==='due'?`<button class="subtle-button" data-open-lead="${x.leadId}">Abrir para enviar</button>`:''}${['pending','due'].includes(x.status)?`<button class="text-button" data-cancel-schedule="${x.id}">Cancelar</button>`:''}</div></article>`).join(''):'<p>No hay envíos programados.</p>';}
function localInput(d){const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;}
function schedulePreview(){const channel=$('#scheduleChannel').value,leads=state.leads.filter(l=>selected.has(l.id));const blocked=l=>{const b=channel==='email'?l.emailBlock:l.block;return b&&!/^(Revisar hotel|Cupo)/.test(b)?b:'';};const ok=leads.filter(l=>!blocked(l));$('#schedulePreviewSummary').textContent=`${leads.length} seleccionados · ${ok.length} se pueden programar por ${channel==='email'?'email':'Instagram'}.`;$('#schedulePreview').innerHTML=leads.map(l=>`<article><strong>${esc(l.name)} · ${esc(channel==='email'?l.email||'sin email':'@'+l.handle)}</strong><p>${esc(l.message)}</p>${blocked(l)?`<small>${esc(blocked(l))}</small>`:''}</article>`).join('');$('#confirmSchedule').dataset.ids=JSON.stringify(ok.map(l=>l.id));$('#confirmSchedule').disabled=!$('#scheduleConsent').checked||!ok.length;}
$('#scheduleSelection').onclick=()=>{const d=new Date(Date.now()+864e5);d.setHours(9,0,0,0);$('#scheduleAt').value=localInput(d);$('#scheduleAt').min=localInput(new Date());$('#scheduleConsent').checked=false;schedulePreview();$('#scheduleDialog').showModal();};$('#scheduleChannel').onchange=schedulePreview;$('#scheduleConsent').onchange=schedulePreview;
$('#confirmSchedule').onclick=()=>run(async()=>{const at=new Date($('#scheduleAt').value);if(!Number.isFinite(at.getTime()))throw Error('Elegí fecha y hora.');const channel=$('#scheduleChannel').value;if(channel==='email'&&!state.email.configured)toast('Acordate de configurar tu email en Ajustes antes de esa hora.',true);const r=await api('schedule',{ids:JSON.parse($('#confirmSchedule').dataset.ids),channel,at:at.toISOString(),confirm:true});selected.clear();$('#scheduleDialog').close();toast(`${r.ok.length} envíos programados para ${when(at)}${r.skipped.length?' · '+r.skipped.length+' omitidos: '+r.skipped.join(' / '):''}`,r.skipped.length>0);},$('#confirmSchedule'));
