function renderAssistant(){if(!state?.assistant)return;const a=state.assistant,key=state.user.id+':'+a.history.length+':'+(a.history.at(-1)?.at||'');if(key!==assistantLogKey){$('#assistantLog').innerHTML=a.history.length?a.history.slice(-6).map(h=>`<article class="assistant-turn"><strong>Vos</strong><p>${esc(h.request)}</p><strong>Claude · acciones de Nexo</strong><p>${esc(h.answer)}</p></article>`).join(''):'<div class="assistant-welcome"><strong>¿Qué hacemos hoy?</strong><p>Puedo buscar hoteles para tu oferta, preparar propuestas y actualizar tu planilla.</p></div>';assistantLogKey=key;$('#assistantLog').scrollTop=$('#assistantLog').scrollHeight;}$('#assistantWorking').hidden=a.status!=='running';$('#assistantStage').textContent=a.stage;$('#sendAssistant').disabled=a.status==='running';$$('[data-assistant]').forEach(b=>b.disabled=a.status==='running');$('#reviewAssistantSelection').hidden=!a.preview?.length;$('#assistantDownload').hidden=!a.download;}
