$('#connectOfficialInstagram').onclick=()=>{if(!state.officialInstagram?.configured){toast('La conexión está preparada. Falta configurar la aplicación de Meta y el servicio de autorización de Nexo.',true);return;}const username=$('#instagramSender').value.trim().replace(/^@/,'');const popup=window.open('about:blank','_blank');if(!popup){toast('Permití abrir la ventana de autorización de Instagram.',true);return;}popup.opener=null;run(async()=>{try{const r=await api('instagram/oauth/start',{username});popup.location.href=r.authorizationUrl;toast('Autorizá tu cuenta en la página oficial. Nexo comprobará la conexión al terminar.');}catch(e){popup.close();throw e;}},$('#connectOfficialInstagram'));};
$('#cancelOfficialInstagram').onclick=()=>run(()=>api('instagram/oauth/cancel'));$('#disconnectInstagram').onclick=()=>run(async()=>{await api('instagram/disconnect');toast('Instagram desconectado. Tu historial y las otras conexiones se conservan.');});
function resetInstagramTest(){instagramTestNonce='';$('#instagramTestPreview').hidden=true;$('#instagramTestConsent').checked=false;$('#instagramTestConsent').disabled=true;$('#sendInstagramTest').disabled=true;$('#instagramTestResult').textContent='';}
$('#instagramTestOpen').onclick=()=>{resetInstagramTest();$('#instagramTestTarget').value='';$('#instagramTestFrom').textContent='Cuenta remitente: @'+state.instagram.username;$('#instagramTestDialog').showModal();};$('#instagramTestTarget').oninput=resetInstagramTest;$('#instagramTestText').oninput=resetInstagramTest;
$('#prepareInstagramTest').onclick=()=>run(async()=>{resetInstagramTest();const r=await api('instagram/test/preview',{target:$('#instagramTestTarget').value,text:$('#instagramTestText').value});instagramTestNonce=r.preview.nonce;$('#instagramTestPreview').textContent='De @'+r.preview.from+' a @'+r.preview.target+'\n\n'+r.preview.text;$('#instagramTestPreview').style.whiteSpace='pre-wrap';$('#instagramTestPreview').hidden=false;$('#instagramTestConsent').disabled=false;},$('#prepareInstagramTest'));
