 const ig=state?.igSender||{},mail=state?.emailQueue||{},hasIg=!!ig.items?.length,hasMail=!!mail.items?.length;
 $('#taskBoard').hidden=!hasIg&&!hasMail;$('#taskTitle').textContent='Tus envíos · podés seguir trabajando';
 $('#taskDetail').textContent=[hasIg?`Instagram: ${ig.sent||0}/${ig.total||ig.items.length} enviados · ${ig.message||ig.status}`:'',hasMail?`Email: ${mail.sent||0}/${mail.items.length} enviados · ${mail.message||mail.status}`:''].filter(Boolean).join(' | ');
